{
  "detectors": [
    {
      "name": "too_few_nodes",
      "hypothesis": "Attempts with node_count <= 3 fail the certificate",
      "spec": {
        "all": [
          {
            "field": "node_count",
            "op": "<=",
            "value": 3
          }
        ]
      }
    },
    {
      "name": "insufficient_measured_exactness",
      "hypothesis": "Attempts with measured_exactness_degree < 7 fail the certificate",
      "spec": {
        "all": [
          {
            "field": "measured_exactness_degree",
            "op": "<",
            "value": 7
          }
        ]
      }
    },
    {
      "name": "large_monomial_error",
      "hypothesis": "Attempts with max_monomial_error > 1e-4 fail the certificate",
      "spec": {
        "all": [
          {
            "field": "max_monomial_error",
            "op": "abs_gt",
            "value": 0.0001
          }
        ]
      }
    },
    {
      "name": "sandbox_failure_with_code",
      "hypothesis": "Attempts that provided code but did not pass sandbox_ok (sandbox_ok == False and has_code == True) fail the certificate",
      "spec": {
        "all": [
          {
            "field": "has_code",
            "op": "==",
            "value": true
          },
          {
            "field": "sandbox_ok",
            "op": "==",
            "value": false
          }
        ]
      }
    }
  ]
}
